properties.query:
// Detects suspicious bitsadmin usage
//  BITSAdmin is a command-line tool built into Microsoft Windows that allows for queuing file transfer jobs, but has been used by threat actores for exfilration
let cmd_any = dynamic(["addfile","create","resume","complete"]);
let ProcessNames = dynamic(["bitsadmin.exe"]);
_Im_ProcessCreate(targetprocess_has_any=ProcessNames,commandline_has_any=cmd_any)
| extend
    Account = tostring(column_ifexists("ActorUsername", "")),
    AccountDomain = tostring(column_ifexists("ActorUserDomain", "")),
    Computer = tostring(column_ifexists("DvcHostname", "")),
    ProcessName = tostring(column_ifexists("TargetProcessName", "")),
    ProcessId = tostring(column_ifexists("TargetProcessId", "")),
    CommandLine = tostring(column_ifexists("CommandLine", ""))
| where isnotempty(ProcessName)
